export declare const morandiForestTheme = "/* \u83AB\u5170\u8FEA\u68EE\u6797\u98CE\u683C */\n#wemd {\n  padding: 5px 22px;\n  max-width: 677px;\n  margin: 0 auto;\n  font-family: \"Optima\", \"Georgia\", \"PingFang SC\", \"Microsoft YaHei\", serif;\n  color: #2F3E32;\n  background-color: transparent;\n  /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n  word-break: break-word;\n}\n\n/* \u6BB5\u843D */\n#wemd p {\n  margin-top: 26px;\n  margin-bottom: 26px;\n  line-height: 2.0;\n  letter-spacing: 0.5px;\n  text-align: justify;\n  color: #3A4D39;\n  font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 */\n#wemd h1 {\n  margin-top: 60px;\n  margin-bottom: 50px;\n  text-align: center;\n}\n\n#wemd h1 .content {\n  display: inline-block;\n  font-size: 24px;\n  font-weight: normal;\n  color: #1A261D;\n  padding: 12px 24px;\n  border: 1px solid #739072;\n  border-radius: 2px;\n  background-color: #F1F4F0;\n  letter-spacing: 2px;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n  display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 */\n#wemd h2 {\n  margin-top: 50px;\n  margin-bottom: 24px;\n  text-align: left;\n  border-bottom: 1px solid #E8EBE9;\n  padding-bottom: 10px;\n}\n\n#wemd h2 .content {\n  display: inline-block;\n  font-size: 19px;\n  font-weight: 700;\n  color: #4F6F52;\n  padding-left: 12px;\n  border-left: 5px solid #4F6F52;\n  line-height: 1.2;\n  letter-spacing: 1px;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n  display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 */\n#wemd h3 {\n  margin-top: 40px;\n  margin-bottom: 20px;\n  text-align: center;\n}\n\n#wemd h3 .content {\n  font-size: 17px;\n  font-weight: bold;\n  color: #739072;\n  display: inline-block;\n  border-bottom: 2px dotted #739072;\n  padding-bottom: 4px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n  display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 */\n#wemd h4 {\n  margin-top: 30px;\n  margin-bottom: 15px;\n  text-align: left;\n}\n\n#wemd h4 .content {\n  display: inline-block;\n  font-size: 15px;\n  font-weight: 700;\n  color: #fff;\n  background-color: #86A789;\n  padding: 4px 10px;\n  border-radius: 4px;\n  line-height: 1.4;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n  display: none;\n}\n\n/* \u5217\u8868 */\n#wemd ul {\n  list-style-type: disc;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #86A789;\n}\n\n#wemd ul li {\n  margin-bottom: 12px;\n  line-height: 1.8;\n}\n\n#wemd li section {\n  color: #3A4D39;\n  font-size: 16px;\n}\n\n/* \u6709\u5E8F\u5217\u8868 */\n#wemd ol {\n  list-style-type: decimal;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #4F6F52;\n  font-weight: bold;\n}\n\n#wemd ul ul {\n  list-style-type: circle;\n  color: #4F6F52;\n  margin-top: 8px;\n}\n\n#wemd ol ol {\n  list-style-type: lower-alpha;\n  color: #739072;\n}\n\n#wemd ol li {\n  margin-bottom: 12px;\n  line-height: 1.8;\n}\n\n#wemd ol li section {\n  color: #3A4D39;\n  font-weight: normal;\n  font-size: 16px;\n}\n\n/* \u5F15\u7528 */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 36px 0;\n  padding: 24px;\n  background-color: #F6F8F6;\n  border: 1px dashed #739072;\n  border-radius: 8px;\n  overflow: visible !important;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #556B58;\n  font-size: 15px;\n  line-height: 1.8;\n  font-family: \"KaiTi\", \"STKaiti\", serif;\n}\n\n/* \u94FE\u63A5 */\n#wemd a {\n  color: #4F6F52;\n  text-decoration: none;\n  border-bottom: 1px solid #4F6F52;\n  font-weight: 600;\n  padding-bottom: 0px;\n}\n\n/* \u52A0\u7C97 */\n#wemd strong {\n  color: #1A261D;\n  font-weight: 700;\n  background: linear-gradient(to top, rgba(134, 167, 137, 0.4) 50%, transparent 50%);\n  margin: 0 2px;\n  padding: 0 2px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n  color: #739072;\n  font-style: italic;\n}\n\n#wemd em strong {\n  color: #4F6F52;\n}\n\n/* \u9AD8\u4EAE - \u6D45\u7EFF\u80CC\u666F */\n#wemd mark {\n  background: linear-gradient(to top, rgba(134, 167, 137, 0.3) 50%, transparent 50%);\n  color: #1A261D;\n  padding: 0 2px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n  text-decoration: line-through;\n  color: #889E8B;\n}\n\n/* \n * \u5206\u9694\u7EBF \n * \u4FEE\u590D\u4E86\u8FD9\u91CC\u65E0\u6548\u7684\u989C\u8272\u4EE3\u7801 #D2DSD4\n */\n#wemd hr {\n  margin: 60px auto;\n  border: 0;\n  height: 1px;\n  background-color: #D2D4D4;\n  /* \u5DF2\u4FEE\u6B63 */\n  width: 60%;\n}\n\n/* \u56FE\u7247 */\n#wemd img {\n  display: block;\n  margin: 40px auto;\n  width: 100%;\n  border-radius: 2px;\n  box-shadow: 0 8px 20px rgba(79, 111, 82, 0.15);\n  padding: 6px;\n  background: #fff;\n  border: 1px solid #eee;\n}\n\n#wemd figcaption {\n  font-size: 13px;\n  color: #889E8B;\n  margin-top: 10px;\n  font-family: serif;\n}\n\n/* \u884C\u5185\u4EE3\u7801 */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  color: #4F6F52;\n  background: #EDF1EE;\n  border: none;\n  padding: 3px 6px;\n  margin: 0 4px;\n  border-radius: 4px;\n  font-size: 14px;\n  font-family: sans-serif;\n}\n\n/* \u4EE3\u7801\u5757 */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n  display: block;\n  padding: 20px;\n  background: #F0F2F0;\n  /* color \u7531 .hljs \u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n  font-size: 13px;\n  line-height: 1.6;\n  border-radius: 6px;\n  font-family: sans-serif;\n  overflow-x: auto;\n  white-space: pre;\n  min-width: max-content;\n  border: 1px solid #DCE3DD;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u6DF1\u7EFF\u8272 */\n#wemd pre code:not(.hljs) {\n  color: #3A4D39;\n  background: #F0F2F0;\n  border: 1px solid #DCE3DD;\n}\n\n/* \n * \u8868\u683C \n * \u4FEE\u590D\u4E86\u8FD9\u91CC\u65E0\u6548\u7684\u989C\u8272\u4EE3\u7801 #D2DSD4\n */\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 40px 0;\n  font-size: 14px;\n  border: 1px solid #D2D4D4;\n  /* \u5DF2\u4FEE\u6B63 */\n}\n\n#wemd table tr th {\n  background: #EDF1EE;\n  color: #4F6F52;\n  font-weight: 700;\n  border: 1px solid #D2D4D4;\n  /* \u5DF2\u4FEE\u6B63 */\n  padding: 12px 10px;\n  text-align: left;\n}\n\n#wemd table tr td {\n  border: 1px solid #D2D4D4;\n  /* \u5DF2\u4FEE\u6B63 */\n  padding: 12px 10px;\n  color: #555;\n  background: #fff;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #4F6F52;\n}\n\n#wemd .footnotes-sep {\n  border-top: 1px solid #E8EBE9;\n  padding-top: 20px;\n  margin-top: 60px;\n  font-size: 12px;\n  color: #B0BEB3;\n  text-align: center;\n}\n\n#wemd .footnote-num {\n  font-weight: bold;\n  color: #739072;\n  margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n  color: #889E8B;\n  font-size: 12px;\n  margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n  max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n  max-width: 100%;\n  vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u83AB\u5170\u8FEA\u68EE\u6797\u98CE\u683C */\n#wemd .callout {\n  margin: 30px 0;\n  padding: 20px;\n  background: #F6F8F6;\n  border: 1px dashed #739072;\n  border-radius: 8px;\n}\n\n#wemd .callout-title {\n  font-weight: 700;\n  margin-bottom: 10px;\n  color: #4F6F52;\n  font-size: 15px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n  margin-right: 6px;\n}\n\n#wemd .callout-note { border-left: 4px solid #739072; }\n#wemd .callout-tip { border-left: 4px solid #86A789; }\n#wemd .callout-important { border-left: 4px solid #4F6F52; }\n#wemd .callout-warning { border-left: 4px solid #D98C45; }\n#wemd .callout-caution { border-left: 4px solid #B33D25; }\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
